B.ajT=new A.bo("Huckable","Increase range of abilities by {Level/3}",B.M,!1)
B.ajA=new A.bo("Dangerous","Target all characters range 1 of any of the targets and deal {Level/3 d6} damage to them.",B.M,!1)
B.ajY=new A.bo("Dampening","Target all enemies range {Level/3} of any of the targets and reduce their shields by {Level/3 d6}.",B.M,!1)
B.ajz=new A.bo("Energizing","Target all Allies range {Level/3} of any of the targets and they gain {Level/3} speed until the end of their next turn.",B.M,!1)
